1401:                 /timeout/i.test(msg) ||
1402:                 /abort/i.test(msg) ||
1403:                 /ETIMEDOUT/i.test(msg) ||
1404:                 /ECONNRESET/i.test(msg) ||
1405:                 /fetch failed/i.test(msg);
