1407:                 // Retry without startIndex — GeoServer doesn't support paging
1408:                 usedFallback = true;
1409:                 const fallbackCount = Math.min(WFS_MAX_FEATURES, WFS_PAGE_SIZE);
1410:                 const fallbackUrl = buildWfsUrl({
1411:                     service: "WFS",
1412:                     version: "2.0.0",
1413:                     request: "GetFeature",
1414:                     typeNames: wfsLayerName,
1415:                     outputFormat: "application/json",
1416:                     srsName,
1417:                     count: fallbackCount,
1418:                     CQL_FILTER: cqlFilter,
1419:                 });
1420:                 page = await fetchJsonWithTimeout<any>(fallbackUrl, WFS_TIMEOUT_MS);
1421:                 partial = numberMatched !== null ? numberMatched > fallbackCount : true;
1422:                 warnings.push(
1423:                     numberMatched !== null && numberMatched > fallbackCount
1424:                         ? `WFS sem paginacao com startIndex para esta camada; total estimado ${numberMatched} feicoes, calculo limitado a ${fallbackCount}.`
1425:                         : `WFS sem paginacao com startIndex para esta camada; resultado limitado a ate ${fallbackCount} feicoes.`,
1426:                 );
1427:             } else {
1428:                 throw error;
1429:             }
1430:         }
1431: 
1432:         const features = Array.isArray(page?.features) ? page.features : [];
1433:         if (!features.length) break;
1434: 
1435:         for (const f of features) {
1436:             allFeatures.push({
1437:                 geometry: f.geometry || null,
1438:                 properties: f.properties || {},
1439:             });
1440:         }
1441: 
1442:         startIndex += features.length;
1443:         if (usedFallback) break;
1444:         if (features.length < pageSize) break;
1445:     }
